    {
      "id": "E5334938774b442cd",
      "pertinente": true,
      "tipo": "explicacao_tecnica",
      "achados": [
        {
          "proposicao": "O diagnóstico de válvulas de controle pode ser feito por técnica não invasiva a partir de variáveis medidas na própria válvula e interpretadas por regras de lógica fuzzy.",
          "trechos": [
            "E5334938774b442cd:0:697",
            "E5334938774b442cd:697:1389"
          ],
          "condicoes": [
            "depende da aquisição das medidas de base da válvula",
            "usa regras escritas por especialistas",
            "o sistema descrito foi implementado com posicionador inteligente e software específico"
          ],
          "limites": [
            "a fonte descreve uma metodologia e implementação específica, não um critério universal",
            "não apresenta nesta amostra métricas de desempenho, limites de detecção ou cobertura diagnóstica completa"
          ]
        },
        {
          "proposicao": "Pressão de ar do atuador e deslocamento do obturador são usados como parâmetros de entrada para inferir sintomas como falha, vazamento, atrito/fricção e danos.",
          "trechos": [
            "E5334938774b442cd:0:697",
            "E5334938774b442cd:697:1389"
          ],
          "condicoes": [
            "os sinais são recebidos de um posicionador inteligente instalado junto à válvula",
            "as inferências dependem do conjunto de regras adotado"
          ],
          "limites": [
            "os sintomas listados aparecem como capacidades pretendidas do sistema, sem comprovação quantitativa neste excerto",
            "não há distinção, no trecho, entre diagnóstico de sede, atuador, posicionador e instrumentação associada"
          ]
        },
        {
          "proposicao": "O monitoramento e diagnóstico foram concebidos para identificar defeitos durante a operação normal da instalação.",
          "trechos": [
            "E5334938774b442cd:1389:2089"
          ],
          "condicoes": [
            "aplicado em equipamento laboratorial que simula parte de uma planta a vapor",
            "o objetivo declarado inclui confiabilidade e segurança"
          ],
          "limites": [
            "o contexto principal é instalação laboratorial ligada a planta a vapor, não FPSO",
            "não há evidência neste trecho de validação em ambiente offshore"
          ]
        }
      ]
    },
    {
      "id": "Ec4fdf4273907573d",
      "pertinente": false,
      "tipo": "explicacao_tecnica",
      "achados": [
        {
          "proposicao": "O texto trata de controle de nível/interface em sistema submarino de separação e reinjeção, com preocupação de robustez frente a perturbações e atrasos.",
          "trechos": [
            "Ec4fdf4273907573d:0:698",
            "Ec4fdf4273907573d:698:1395",
            "Ec4fdf4273907573d:1395:2092"
          ],
          "condicoes": [
            "focado no SSAO e no controle do nível de interface"
          ],
          "limites": [
            "não aborda de forma direta posicionadores, atuadores, solenoides, atrito, hunting, vazamento de sede ou diagnóstico de válvulas",
            "o recorte é de controle de processo, não de integridade de elementos finais"
          ]
        }
      ]
    },
    {
      "id": "Ecce9bcb5edb3ab39",
      "pertinente": true,
      "tipo": "resultado_experimental",
      "achados": [
        {
          "proposicao": "Comissionamento incompleto ou incorreto de válvulas e controles pode deixar funções previstas em projeto indisponíveis ou degradadas na operação.",
          "trechos": [
            "Ecce9bcb5edb3ab39:0:697",
            "Ecce9bcb5edb3ab39:697:1394"
          ],
          "condicoes": [
            "constavam pendências de conversão para comando automático, de respeito dos comandos da IHM pelos atuadores e de comissionamento de controles/transmissores",
            "o achado decorre de investigação de incidente em unidade específica"
          ],
          "limites": [
            "é evidência de caso investigado, não regra universal",
            "o trecho não detalha mecanismo físico de falha de atuador, posicionador ou solenoide"
          ]
        },
        {
          "proposicao": "Uma válvula prevista em P&ID como operada remotamente e com controle de posição foi comissionada apenas como totalmente aberta ou fechada, mostrando incompatibilidade entre projeto e configuração efetiva.",
          "trechos": [
            "Ecce9bcb5edb3ab39:697:1394",
            "Ecce9bcb5edb3ab39:1394:2094"
          ],
          "condicoes": [
            "o documento de projeto indicava controle de posição",
            "o indicador de posição ainda estava por comissionar"
          ],
          "limites": [
            "o caso refere-se à válvula OT-022 em uma investigação específica",
            "o trecho não informa as causas completas da divergência nem a solução aplicada"
          ]
        },
        {
          "proposicao": "A disponibilidade de informações na IHM não assegura, por si só, a completa funcionalidade do controle, pois havia sinais disponíveis enquanto aspectos de comissionamento permaneciam pendentes.",
          "trechos": [
            "Ecce9bcb5edb3ab39:1394:2094"
          ],
          "condicoes": [
            "as medições de pressão de sucção e descarga estavam disponíveis na IHM",
            "a análise refere-se à bomba de stripping e seu controle associado"
          ],
          "limites": [
            "o trecho é parcial e não informa todos os sinais ou malhas afetados",
            "não trata especificamente de atrito, hunting ou vazamento de sede"
          ]
        }
      ]
    },
    {
      "id": "E922e2756c8083317",
      "pertinente": false,
      "tipo": "explicacao_tecnica",
      "achados": [
        {
          "proposicao": "O texto é majoritariamente glossário de termos de sistemas submarinos e define choke como válvula de controle de vazão utilizada em equipamentos submarinos.",
          "trechos": [
            "E922e2756c8083317:0:699"
          ],
          "condicoes": [],
          "limites": [
            "não desenvolve mecanismos, diagnóstico, manutenção ou falhas de elementos finais",
            "o foco é terminológico, com baixa utilidade didática para o recorte solicitado"
          ]
        }
      ]
    },
    {
      "id": "E7597761647a18669",
      "pertinente": true,
      "tipo": "explicacao_tecnica",
      "achados": [
        {
          "proposicao": "Em poços inteligentes, válvulas de controle e packers são combinados para permitir controle e monitoramento independente de diferentes regiões do poço.",
          "trechos": [
            "E7597761647a18669:0:697"
          ],
          "condicoes": [
            "depende da instalação de packers para vedar a região anular",
            "o foco do trabalho é a quantidade e posição das válvulas e packers"
          ],
          "limites": [
            "o contexto é poço inteligente, não válvula de controle de processo em FPSO",
            "não trata de diagnóstico de atrito, hunting, vazamento de sede ou acessórios como posicionadores e solenoides"
          ]
        },
        {
          "proposicao": "As válvulas podem ser classificadas pelas alternativas de regulagem oferecidas, pelo mecanismo interno de fechamento, modo de acionamento e mecanismo de controle.",
          "trechos": [
            "E7597761647a18669:697:1397"
          ],
          "condicoes": [
            "a fonte destaca que, em estudos de reservatórios, a principal característica avaliada costuma ser a quantidade de alternativas de controle"
          ],
          "limites": [
            "é uma classificação geral voltada ao contexto de reservatórios",
            "não detalha compatibilidade com atuadores, posicionadores ou desempenho dinâmico"
          ]
        },
        {
          "proposicao": "Quanto às alternativas de controle, as válvulas são apresentadas como abre-fecha/on-off, multiposição e variação contínua, com diferenças na reversibilidade e granularidade do ajuste de vazão.",
          "trechos": [
            "E7597761647a18669:1397:2089",
            "E7597761647a18669:2089:2323"
          ],
          "condicoes": [
            "válvulas abre-fecha possuem dois estágios",
            "a reversibilidade do fechamento pode variar",
            "nas multiposição há diversos estágios de abertura",
            "na variação contínua o texto fala em controle 'em teoria' infinitesimal"
          ],
          "limites": [
            "a formulação sobre controle contínuo é teórica no próprio texto",
            "não há ligação direta com falhas, calibração ou manutenção dos elementos finais"
          ]
        }
      ]
    },
    {
      "id": "Ef1fd794d3fafdea7",
      "pertinente": true,
      "tipo": "explicacao_tecnica",
      "achados": [
        {
          "proposicao": "O sistema descrito eliminou a necessidade de uma válvula choke na saída de gás para equilibrar perda de carga, resultando em redução do número de módulos do sistema.",
          "trechos": [
            "Ef1fd794d3fafdea7:0:695"
          ],
          "condicoes": [
            "relacionado ao arranjo específico do SSAO"
          ],
          "limites": [
            "é consequência de uma solução particular de projeto",
            "não constitui regra geral de seleção ou eliminação de choke"
          ]
        },
        {
          "proposicao": "A medição do nível de interface por tecnologia nucleônica baseada na atenuação de raios gama fornece sinal que é convertido e usado no controle do processo.",
          "trechos": [
            "Ef1fd794d3fafdea7:0:695",
            "Ef1fd794d3fafdea7:695:1392"
          ],
          "condicoes": [
            "o medidor usa tubo de emissão e tubos de captação de sinal",
            "o sinal é comparado com tabela previamente carregada",
            "o sistema real teria transmissão serial ao controlador"
          ],
          "limites": [
            "o foco é sensor e malha de nível/interface, não elementos finais do recorte principal",
            "não aborda posicionadores, solenoides, atrito ou vazamento de sede"
          ]
        },
        {
          "proposicao": "O controlador atua sobre um variador de frequência da bomba de injeção para manter o nível de interface, com filosofia PI ajustada por metodologia citada na fonte.",
          "trechos": [
            "Ef1fd794d3fafdea7:695:1392",
            "Ef1fd794d3fafdea7:1392:2092"
          ],
          "condicoes": [
            "aplicado ao controle do nível de interface água-óleo no SSAO"
          ],
          "limites": [
            "o elemento final aqui é acionamento de bomba, não válvula de controle",
            "a pertinência ao recorte é apenas indireta"
          ]
        }
      ]
    }
